/bin/bash -c "python3 - <<'PY'
from math import inf

def eta(a,b):
 if b<a: return 1-b/a
 if b>a: return (b-a)/(1-a)
 return 0.0

def uf(p,q,wp,wq):
 return min(wp*eta(a,p)+wq*eta(a,q) for a in [0,1,p,q])

n=400
betas=[0.5,0.59,0.599,0.6,0.601,0.61,0.7,1]
best={b:(inf,None) for b in betas}
cbest=(inf,None)
for i in range(n+1):
 x=2/7+(3/7)*i/n
 for j in range(n+1):
  z=j/n
  fnl=(-2+7*x)/3
  fnr=3*z/7
  err=0.35*x+0.15*z+0.15*fnl+0.35*fnr
  u=uf(x,z,0.35,0.15)+uf(fnl,fnr,0.15,0.35)
  if err<=0.175+1e-12 and u<cbest[0]: cbest=(u,(err,x,z))
  for b in betas:
   d=b*u+(1-b)*err
   if d<best[b][0]-1e-14: best[b]=(d,(u,err,x,z))
print('Figure 2 marginals: prevalence .3,.7; predictions .5,.7; equal weights')
for b,v in best.items(): print('beta',b,'best grid result',v)
print('Best grid constrained error <= .175:',cbest)
t=0.5
x=(1-t)*2/7+t*0.35
z=t*0.35
fnl=(-2+7*x)/3
fnr=3*z/7
u=uf(x,z,0.35,0.15)+uf(fnl,fnr,0.15,0.35)
e=0.35*x+0.15*z+0.15*fnl+0.35*fnr
print('Explicit feasible intermediate classifier:', 'FPRs',(x,z),'FNRs',(fnl,fnr),'unfairness',u,'error',e)
PY"
